// Testable: the dependency arrives through an interface.
public interface IOrderRepository { Order Load(int orderId); }

public class InvoiceService
{
    private readonly IOrderRepository _orders;
    public InvoiceService(IOrderRepository orders) => _orders = orders;

    public decimal Total(int orderId) =>
        _orders.Load(orderId).Lines.Sum(l => l.Price * l.Quantity);
}

// Before: every new customer type edits this method (breaks open-closed).
public decimal Discount(Customer c, decimal total)
{
    if (c.Type == "Staff") return total * 0.20m;
    if (c.Type == "Loyal") return total * 0.10m;
    return 0m;
}

// After: a new rule is a new class; existing code is untouched.
public interface IDiscountRule
{
    bool AppliesTo(Customer c);
    decimal For(decimal total);
}

public class StaffDiscount : IDiscountRule
{
    public bool AppliesTo(Customer c) => c.Type == "Staff";
    public decimal For(decimal total) => total * 0.20m;
}

public class DiscountCalculator
{
    private readonly IEnumerable<IDiscountRule> _rules;
    public DiscountCalculator(IEnumerable<IDiscountRule> rules) => _rules = rules;

    public decimal Discount(Customer c, decimal total) =>
        _rules.FirstOrDefault(r => r.AppliesTo(c))?.For(total) ?? 0m;
}

