// Green: the simplest code that passes.
public class Shipping
{
    private readonly ICarrier _carrier;
    public Shipping(ICarrier carrier) => _carrier = carrier;

    public decimal Rate(decimal orderTotal) =>
        orderTotal > 50m ? 0m : _carrier.BaseRate();
}

// Refactor: with the test green, name the threshold.
private const decimal FreeShippingThreshold = 50m;

// The stub stands in for the real carrier service.
public class StubCarrier : ICarrier
{
    private readonly decimal _rate;
    public StubCarrier(decimal baseRate) => _rate = baseRate;
    public decimal BaseRate() => _rate;
}
